// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // Bound version to a reasonable range to avoid unrealistic behavior
        version = bound(version, 0, 1000000);

        // Call atVersion
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("atVersion(uint256)", version));
        require(success, "call should succeed");

        // The rule: If a call to atVersion succeeds, the returned data should not be empty
        assertTrue(data.length > 0, "atVersion should return non-empty data");
    }
}

