pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // bound version to a reasonable range to avoid exceeding storage
        version = bound(version, 0, type(uint256).max);
        // get current version from C
        uint256 currentVersion = c.latestVersion();
        // only test when version matches currentVersion (the bug is in atVersion returning zero)
        vm.assume(version == currentVersion);
        // call atVersion with the current version
        (uint256 retVersion, uint256 timestamp, int256 price) = c.atVersion(version);
        // assert that the price is non-zero (the reference should have a non-zero price when version matches current)
        assertTrue(price != 0, "Price should be non-zero when version matches currentVersion");
    }
}

