pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        vm.assume(version <= 100);
        // Call atVersion and currentVersion on the same version
        // Since both reference and mutant have the same behavior for undefined versions,
        // we use the contract's own currentVersion to get a valid version
        try c.atVersion(version) returns (IOracleProvider.OracleVersion memory v) {
            // For the reference, atVersion returns the actual price; for mutant it returns 0
            // The rule: the price from atVersion should equal the price from currentVersion
            // when the version matches currentVersion's version.
            IOracleProvider.OracleVersion memory current = c.currentVersion();
            if (v.version == current.version) {
                assertTrue(v.price == current.price);
            }
        } catch {
            // If both revert, that's fine
        }
    }
}

