pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // bound version to avoid out-of-gas or unrealistic values
        version = bound(version, 0, 100);

        // Ensure we have at least one oracle version set up
        vm.assume(c.latestVersion() > 0 || version == 0);

        // Get the latest version from the contract
        uint256 latestVersion = c.latestVersion();

        // If version is less than latest version, we can still test
        if (version <= latestVersion) {
            // Get the price from currentVersion
            (uint256 cvVersion, uint256 cvTimestamp, int256 cvPrice) = c.currentVersion();

            // Get the price from atVersion with the same version
            (uint256 avVersion, uint256 avTimestamp, int256 avPrice) = c.atVersion(cvVersion);

            // Assert that the prices match
            assertTrue(cvPrice == avPrice, "Price mismatch between currentVersion and atVersion for current version");
        }
    }
}

