import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Ensure there is at least one oracle version by syncing
        // (c.sync is not public, so we call settle which triggers sync)
        // However, we need a populated oracle; we can't call sync directly.
        // The invariant is that currentVersion().price equals atVersion(currentVersion().version).price
        // We call currentVersion() and atVersion() – but if oracle has no version, it reverts.
        // We use vm.assume to ensure version > 0.
        // We read currentVersion(), store its version, then call atVersion with that version.
        // We assert prices are equal.

        // To get the oracle, we need the product's oracle address.
        // However, OracleProvider is an interface; we can't instantiate it here.
        // The test must work with the deployed C, which requires a real oracle.
        // Since the problem says we can assume the oracle is set up, we just call.
        // But to avoid reverts due to no oracle, we wrap in try/catch.

        // Actually, we can just call currentVersion and atVersion directly.
        // If they revert, the fuzzer will skip those inputs.

        (bool success1, bytes memory data1) = address(c).staticcall(abi.encodeWithSignature("currentVersion()"));
        if (!success1) return;

        (uint256 version, uint256 timestamp, int256 price) = abi.decode(data1, (uint256, uint256, int256));

        // Now call atVersion with the same version
        (bool success2, bytes memory data2) = address(c).staticcall(abi.encodeWithSignature("atVersion(uint256)", version));
        if (!success2) return;

        (uint256 version2, uint256 timestamp2, int256 price2) = abi.decode(data2, (uint256, uint256, int256));

        // The invariant: both calls should return the same price
        assertTrue(price == price2, "currentVersion price must match atVersion price for same version");
    }
}

