pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialMakerLimit) public {
        // Bind to a reasonable range to avoid overflow issues
        initialMakerLimit = bound(initialMakerLimit, 0, type(uint128).max);

        // Assume that the initial maker limit (if we could set it) is known; but since we cannot set it, 
        // we compare the stored value across multiple calls to ensure consistency
        // The invariant: calling makerLimit() twice returns the same value (unless mutated to constant)
        // This fails when mutant returns a fixed value that might differ from the actual storage

        // We need to somehow change the maker limit; but the contract doesn't allow external setting.
        // However, the invariant is that makerLimit() returns the stored value, which should not change.
        // The bug returns a constant, so comparing two calls will show equality but the rule must be
        // that it returns the same as another function that correctly reads the stored value.
        // Since there's no other getter for maker limit, the only way to detect the bug is:
        // If we could change the stored value, but we can't. So we need a different approach:
        // The rule: makerLimit() must be a function that returns the actual stored state variable.
        // The mutant returns 1e18 always. But the original also returns 1e18 if initialized that way.
        // The only difference is if the storage changes, the mutant won't reflect it.
        // Since we cannot change the value, the test must rely on external behavior.
        // After reinitialization? No. 
        // Alternative: We can check that makerLimit() is consistent with utilization buffer which uses same storage?
        // No.
        // The bug fixes the return to 1e18. The original returns whatever is stored. 
        // Original storage default is 0. So the original returns 0, mutant returns 1e18.
        // So we assert that initially makerLimit() returns 0.

        // Since we cannot set a non-zero maker limit, the stored value after initialization is 0.
        // The mutant returns 1e18, so this assertion will catch it.
        assertTrue(c.makerLimit().eq(UFixed18.wrap(0)), "makerLimit should be 0 initially");
    }
}

